<script setup lang="ts">
import { computed, onActivated, onBeforeUnmount, onDeactivated, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import dayjs from 'dayjs'
import * as api from '@/api/modules/schedule'
import type { ScheduleOptions, ScheduleQuery, ScheduleRow } from '@/api/modules/schedule'
import type { CellValue, CollaborationRow, PlanField, PlanHistory } from '@/types/collaboration'
import { useCachedRequest } from '@/composables/useCachedRequest'
import { useUserStore } from '@/stores/user'
import { useCollaborationWorkspace } from '@/stores/collaborationWorkspace'
import { acceptanceNames, groupNames, isCollaborationEntry, moldStatuses, parseCell, parseClipboard, rowKey, statusNames, validateMoldRow } from '@/utils/collaboration'
import FixedTableViewport from '@/components/FixedTableViewport/index.vue'
import CollaborationCell from '@/views/collaboration/components/CollaborationCell.vue'
import CollaborationImportDialog from '@/views/collaboration/components/CollaborationImportDialog.vue'
defineOptions({ name: 'MoldScheduleView' })
const user = useUserStore(), workspace = useCollaborationWorkspace(), router = useRouter(), route = useRoute(), drafts = workspace.drafts
const options = ref<ScheduleOptions>(), error = ref(''), keyword = ref(''), productLineId = ref<number>(), status = ref(''), mineOnly = ref(false), overdueOnly = ref(false), page = ref(1), size = ref(50), group = ref(''), layer = ref('plan'), expanded = ref(false), saving = ref(false)
const presentation = ref('table'), expandedParts = ref(new Set<number>())
const request = useCachedRequest(api.getSchedulePage), rows = computed(() => request.hasCurrentData.value ? request.data.value?.content || [] : []), total = computed(() => request.data.value?.totalElements || 0)
const moldDrafts = computed(() => [...drafts.rows].filter(([, d]) => !!d.source.moldSetId)), dirtyCount = computed(() => moldDrafts.value.reduce((n, [, d]) => n + d.changes.size, 0))
const value = (row: CollaborationRow, key: string) => drafts.value(row, key), dirty = (row: CollaborationRow, key: string) => drafts.rows.get(rowKey(row))?.changes.has(key), can = (f: PlanField) => !!options.value?.writableGroups.includes(f.group) && user.hasPermission('schedule:write')
const field = (key: string) => options.value?.moldFields.find(f => f.key === key)
const layerKeys: Record<string, string[]> = {
  plan: ['planStartDate','openedDate','manufacturingDays','holidayDays','extraDays','ownerUserId','plannedMoldDeliveryDate','logisticsOwnerUserId','plannedFactoryArrivalDate','mexicoOwnerUserId','plannedAcceptanceDate','productionOwnerUserId','plannedProductionDate'],
  forecast: ['forecastDeliveryDate','forecastFactoryDate','forecastAcceptanceDate','forecastProductionDate','scheduleNotes'],
  actual: ['openedDate','actualSupplierTrialDate','actualShipDate','actualMexicoArrivalDate','actualPortArrivalDate','actualTrialDate','actualProductionDate','marketReadyDate']
}
const columns = computed(() => layerKeys[layer.value].map(field).filter((f): f is PlanField => !!f && (!group.value || f.group === group.value)))
const planKeys = ['planStartDate','openedDate','manufacturingDays','holidayDays','extraDays','plannedMoldDeliveryDate','plannedFactoryArrivalDate','plannedAcceptanceDate','plannedProductionDate']
const partColumns = computed(() => ['pc','tpu'].map(p => ({ part: p.toUpperCase(), fields: [p+'Status',p+'SignedDate',p+'FactoryArrivalDate',p+'AcceptanceStatus',p+'AcceptanceDate',p+'AcceptanceIssues'].map(field).filter((f): f is PlanField => !!f) })))
interface TimelineStep { key: string; title: string; plan?: string; forecast?: string; actual: { key: string; label: string }[] }
// Presentation-only mappings: dates remain the shared saved fields or explicitly marked drafts.
const milestones: TimelineStep[] = [
  { key:'opening',title:'开模',plan:'planStartDate',actual:[{key:'openedDate',label:'实际开模'}] },
  { key:'delivery',title:'制模 / 发模',plan:'plannedMoldDeliveryDate',forecast:'forecastDeliveryDate',actual:[{key:'actualSupplierTrialDate',label:'中国制模试模'},{key:'actualShipDate',label:'实际发模'}] },
  { key:'factory',title:'运输 / 到厂',plan:'plannedFactoryArrivalDate',forecast:'forecastFactoryDate',actual:[{key:'actualMexicoArrivalDate',label:'实际抵达墨西哥'},{key:'actualPortArrivalDate',label:'实际到港'},{key:'pcFactoryArrivalDate',label:'PC 实际到厂'},{key:'tpuFactoryArrivalDate',label:'TPU 实际到厂'}] },
  { key:'acceptance',title:'验收',plan:'plannedAcceptanceDate',forecast:'forecastAcceptanceDate',actual:[{key:'pcAcceptanceDate',label:'PC 验收日期'},{key:'tpuAcceptanceDate',label:'TPU 验收日期'}] },
  { key:'production',title:'试模 / 量产',plan:'plannedProductionDate',forecast:'forecastProductionDate',actual:[{key:'actualTrialDate',label:'墨西哥实际试模'},{key:'actualProductionDate',label:'墨西哥实际量产'}] },
  { key:'market',title:'上市确认',actual:[{key:'marketReadyDate',label:'实际上市确认'}] }
]
function toggleParts(id: number) { if (expandedParts.value.has(id)) expandedParts.value.delete(id); else expandedParts.value.add(id) }
function partDisplay(row: CollaborationRow, f: PlanField) { const v=value(row,f.key); return f.kind==='acceptance'?acceptanceNames[String(v)] || '未填写':f.kind==='part_status'?({pending:'待制作',making:'制作中',ready:'已完成'} as Record<string,string>)[String(v)] || '未填写':display(v) }
function query(): ScheduleQuery { return { page: page.value, size: size.value, keyword: keyword.value.trim(), productLineId: productLineId.value, status: status.value || undefined, mineOnly: mineOnly.value, overdueOnly: overdueOnly.value, moldSetId: Number(route.query.moldSetId) || undefined } }
let timer: ReturnType<typeof setTimeout> | undefined, active = true, mounted = false, generation = 0
function load(force = false) { return options.value && user.token ? request.execute(query(), force) : Promise.resolve() }
function reset(debounce = false) { clearTimeout(timer); request.invalidate(); page.value = 1; if (debounce) timer = setTimeout(() => void load(), 300); else void load() }
watch(keyword, () => reset(true), { flush: 'sync' }); watch([productLineId,status,mineOnly,overdueOnly,size], () => reset(), { flush: 'sync' })
watch(() => route.query.moldSetId, () => reset())
watch(() => workspace.revision, () => { request.clear(); if (active && mounted) void load() }, { flush: 'sync' })
watch(() => user.token, () => { generation++; clearTimeout(timer); request.clear(); request.data.value = undefined; request.hasCurrentData.value = false; options.value = undefined; detail.value = undefined; history.value = []; detailVisible.value = false; review.value = false; importVisible.value = false; expandedParts.value.clear() }, { flush: 'sync' })
function edit(row: CollaborationRow, f: PlanField, text: string, quiet = false) { if (!can(f)) return; try { drafts.set(row, f.key, parseCell(f, text)) } catch (e) { if (!quiet) ElMessage.warning(e instanceof Error ? e.message : '格式不正确') } }
function paste(row: CollaborationRow, f: PlanField, event: ClipboardEvent) {
  const text = event.clipboardData?.getData('text/plain') || ''; if (!/[\t\n\r]/.test(text)) return; event.preventDefault()
  try { const cells = parseClipboard(text), start = rows.value.findIndex(r => r.moldSetId === row.moldSetId), col = columns.value.findIndex(c => c.key === f.key); const staged: { row: CollaborationRow; field: PlanField; value: CellValue }[] = []
    cells.forEach((r, ri) => r.forEach((t, ci) => { const target = rows.value[start + ri], targetField = columns.value[col + ci]; if (!target || !targetField || !can(targetField)) throw new Error('粘贴超出本页或包含只读列'); staged.push({ row: target, field: targetField, value: parseCell(targetField, t) }) })); staged.forEach(c => drafts.set(c.row, c.field.key, c.value)); ElMessage.success(`已暂存 ${staged.length} 个单元格`) } catch (e) { ElMessage.warning(e instanceof Error ? e.message : '粘贴失败') }
}
function suggestions(row: CollaborationRow) {
  const add = (v: CellValue, n: number): string | null => v ? dayjs(String(v)).add(n,'day').format('YYYY-MM-DD') : null
  const days = value(row,'manufacturingDays') ?? options.value?.styleDays[row.styleName], start = value(row,'openedDate') || value(row,'planStartDate')
  const delivery = days == null ? null : add(start,Number(days)+Number(value(row,'holidayDays') || 0)+Number(value(row,'extraDays') || 0))
  const factory = add(value(row,'forecastDeliveryDate') || value(row,'plannedMoldDeliveryDate') || delivery,options.value?.transportDays || 7)
  const acceptance = add(value(row,'forecastFactoryDate') || value(row,'plannedFactoryArrivalDate') || factory,options.value?.acceptanceDays || 1)
  const production = add(value(row,'forecastAcceptanceDate') || value(row,'plannedAcceptanceDate') || acceptance,options.value?.productionDays || 3)
  return { plannedMoldDeliveryDate: delivery, plannedFactoryArrivalDate: factory, plannedAcceptanceDate: acceptance, plannedProductionDate: production }
}
function adopt(row: CollaborationRow, key: string) { const f = field(key), date = suggestions(row)[key as keyof ReturnType<typeof suggestions>]; if (!f || !can(f) || !date) return; if (value(row,key)) { ElMessage.warning('此计划已有确认日期，建议不会覆盖；请手工更正并填写原因'); return } drafts.set(row,key,date,true) }
const review = ref(false), detailVisible = ref(false), detail = ref<ScheduleRow>(), detailLoading = ref(false), history = ref<PlanHistory[]>([]), importVisible = ref(false)
async function save() {
  const patches = drafts.patches().filter(p => p.entityType === 'mold_set'); if (!patches.length) return
  for (const patch of patches) { const draft = drafts.rows.get(`mold_set:${patch.id}`)!; const message = validateMoldRow(draft.source,key => value(draft.source,key)); if (message) { error.value = message; review.value = true; return } }
  saving.value = true; error.value = ''; let failed = 0, saved = 0
  try { for (let n = 0; n < patches.length; n += 100) { const submitted = patches.slice(n,n+100), results = await api.saveScheduleRows(submitted); results.forEach(r => { drafts.apply(r,submitted.find(p => p.id === r.id)); if (r.status === 'saved') saved++; else failed++; if (detail.value?.moldSetId === r.id && r.row) detail.value = r.row as ScheduleRow }) }
    if (saved) workspace.changed(); else request.clear(); await load(); if (failed) { error.value = `${failed} 行未保存，草稿和冲突已保留`; review.value = true } else { review.value = false; ElMessage.success(`已保存 ${saved} 套排程`) }
  } catch { error.value = '保存未确认完成，草稿已保留' } finally { saving.value = false }
}
async function discard() { try { await ElMessageBox.confirm('撤销所有入口中尚未保存的模具草稿？市场与产量草稿不受影响。','撤销修改'); moldDrafts.value.forEach(([key]) => drafts.rows.delete(key)); error.value = '' } catch {} }
async function reason(row: CollaborationRow) { const d = drafts.rows.get(rowKey(row)); if (!d) return; try { const result = await ElMessageBox.prompt('日期更正、额外周期和人工核对原因','更正说明',{ inputType:'textarea',inputValue:d.reason }); d.reason = result.value.trim() } catch {} }
async function open(row: ScheduleRow) { const ticket = ++generation; detailVisible.value = true; detailLoading.value = true; history.value = []; try { const result = await api.getSchedule(row.moldSetId!); if (ticket === generation) detail.value = result } catch { error.value = '详情加载失败' } finally { if (ticket === generation) detailLoading.value = false } }
async function loadHistory() { if (!detail.value) return; const ticket = generation, result = await api.getScheduleHistory(detail.value.moldSetId!); if (ticket === generation) history.value = result.content }
async function baseline(row: ScheduleRow) { if (drafts.rows.has(rowKey(row))) { ElMessage.warning('请先保存或撤销本套草稿，再确认基准'); return } try { const result = await ElMessageBox.prompt('记录本次计划版本的确认依据，不覆盖以前的基准。','留存计划基准',{inputType:'textarea',inputValidator:v => !!v?.trim() || '请填写确认依据'}); await api.confirmSchedulePlan(row.moldSetId!,Object.fromEntries(planKeys.map(k => [k,(row[k] as CellValue) ?? null])),result.value); workspace.changed(); await load(); ElMessage.success('已留存不可变计划基准') } catch (e) { if (e instanceof Error) error.value = e.message } }
async function refresh() { error.value = ''; await load(true) }
async function remind() { const result = await api.enqueueScheduleReminders(); ElMessage.success(`新增 ${result.created} 条站内提醒，${result.unassigned} 项未指定负责人；未发送外部消息`) }
function openImport() { if (dirtyCount.value) { ElMessage.warning('请先保存或撤销模具草稿，再导入预览'); return } importVisible.value = true }
function unloaded(event: BeforeUnloadEvent) { if (dirtyCount.value) { event.preventDefault(); event.returnValue = '' } }
onBeforeRouteLeave(async to => { if (!dirtyCount.value) return true; try { const shared = isCollaborationEntry(to.path); await ElMessageBox.confirm(shared?'未保存草稿会在协作计划、模具台账、开模排程之间保留。':'还有未保存草稿，离开前确认撤销。','未保存修改',{confirmButtonText:shared?'保留并前往':'撤销并离开',cancelButtonText:'继续填写'}); if (!shared) moldDrafts.value.forEach(([key]) => drafts.rows.delete(key)); return true } catch { return false } })
onMounted(async () => { window.addEventListener('beforeunload',unloaded); const token = user.token; try { const result = await api.getScheduleOptions(); if (token !== user.token) return; options.value = result; await load(); mounted = true } catch { error.value = '排程初始化失败，请检查登录权限并刷新' } })
onActivated(() => { active = true; if (mounted) void load() }); onDeactivated(() => { active = false; clearTimeout(timer); request.invalidate() }); onBeforeUnmount(() => { generation++; clearTimeout(timer); window.removeEventListener('beforeunload',unloaded) })
const display = (v: unknown) => v == null || v === '' ? '未填写' : String(v)
</script>

<template>
  <main class="mold-schedule" :class="{'wide-mode':expanded}">
    <header class="schedule-heading"><div><h2>开模时间管控</h2><p>一行一套 PC＋TPU · 从开模确认到墨西哥验收、试模量产 · 研发归档不终止交付任务</p></div><div class="actions"><el-button @click="expanded=!expanded">{{ expanded?'退出宽屏':'宽屏录入' }}</el-button><el-button @click="refresh">刷新</el-button><el-button v-if="options?.administrator" @click="remind">生成逾期站内提醒</el-button><el-button @click="router.push('/molds')">模具台账</el-button></div></header>
    <section class="schedule-panel">
      <div class="schedule-filters"><el-input v-model="keyword" clearable placeholder="搜索实物编号 / 款式 / 兼容型号 / 厂家" /><el-select v-model="productLineId" clearable placeholder="全部产品线"><el-option v-for="l in options?.productLines" :key="l.productLineId" :value="l.productLineId" :label="l.productName" /></el-select><el-select v-model="status" clearable placeholder="全部进度"><el-option v-for="key in moldStatuses" :key="key" :value="key" :label="statusNames[key]" /><el-option value="market_ready" label="已确认上市" /></el-select><el-checkbox v-model="mineOnly">待我填写</el-checkbox><el-checkbox v-model="overdueOnly">仅逾期</el-checkbox></div>
      <div class="schedule-toolbar"><el-radio-group v-model="presentation" aria-label="排程展示方式"><el-radio-button value="table" data-test="schedule-table-mode">表格</el-radio-button><el-radio-button value="timeline" data-test="schedule-timeline-mode">时间轴</el-radio-button></el-radio-group><el-radio-group v-if="presentation==='table'" v-model="layer"><el-radio-button value="plan">确认计划 / 建议</el-radio-button><el-radio-button value="forecast">当前预测</el-radio-button><el-radio-button value="actual">实际进度</el-radio-button></el-radio-group><el-select v-if="presentation==='table'" v-model="group" clearable placeholder="全部职责"><el-option v-for="g in ['engineering','logistics','mexico']" :key="g" :value="g" :label="groupNames[g as keyof typeof groupNames]" /></el-select><span>共 {{ total }} 套</span><div class="actions"><el-button text @click="api.downloadScheduleTemplate(query())">下载本页模板（含 ID）</el-button><el-button text @click="openImport">Excel 导入预览</el-button></div></div>
      <el-alert title="制作周期按原表款式 12 / 13 / 14 自然日，加人工确认的假期和额外天数；运输 7、验收 1、试模量产 3 天仅作建议，确认后才成为承诺。抵墨、到港、签收、到厂、验收分别记录。" type="info" :closable="false" />
      <el-alert v-if="error || request.error.value" :title="error || request.error.value" type="error" :closable="false" />
      <FixedTableViewport v-if="presentation==='table'" v-slot="{tableHeight}" fill :refresh-key="rows"><el-table :data="rows" :height="tableHeight" v-loading="request.loading.value" row-key="moldSetId" border class="schedule-table">
        <el-table-column type="expand" width="42"><template #default="{row}"><div class="schedule-parts"><section v-for="p in partColumns" :key="p.part"><h3>{{ p.part }} 到厂 / 验收</h3><div v-for="f in p.fields" :key="f.key" class="part-entry"><label>{{ f.label }}</label><CollaborationCell :field="f" :value="value(row,f.key)" :editable="can(f)" :dirty="dirty(row,f.key)" @preview="edit(row,f,$event,true)" @edit="edit(row,f,$event)" /></div></section></div></template></el-table-column>
        <el-table-column fixed="left" label="款式 / 兼容型号 / 实物套" width="290"><template #default="{row}"><strong>{{ row.styleName }}</strong><div>{{ row.compatibleModels }}</div><button class="asset-button" @click="open(row)">{{ row.assetNumber }} · 第 {{ row.setNo }} 套</button><el-tag v-if="drafts.rows.has(rowKey(row))" size="small" type="warning">待保存</el-tag></template></el-table-column>
        <el-table-column v-for="f in columns" :key="f.key" :label="f.label" :width="f.kind==='text'?290:f.key.endsWith('UserId')?210:200"><template #default="{row}"><CollaborationCell :field="f" :value="value(row,f.key)" :editable="can(f)" :users="options?.users" :dirty="dirty(row,f.key)" @preview="edit(row,f,$event,true)" @edit="edit(row,f,$event)" @paste="paste(row,f,$event)" /><div v-if="Object.prototype.hasOwnProperty.call(suggestions(row),f.key)" class="suggestion">建议 {{ display(suggestions(row)[f.key as keyof ReturnType<typeof suggestions>]) }} <el-button v-if="can(f)" link size="small" @click="adopt(row,f.key)">确认采用</el-button></div><div v-if="f.key==='manufacturingDays' && !value(row,f.key)" class="suggestion">款式默认 {{ options?.styleDays[row.styleName] || '待人工确认' }} 天</div></template></el-table-column>
        <el-table-column label="基准 / 交付进度" width="220"><template #default="{row}"><el-tag>{{ statusNames[row.scheduleStatus] || (row.scheduleStatus==='market_ready'?'已确认上市':row.scheduleStatus) }}</el-tag><p>基准 V{{ row.planVersion || 0 }} <span v-if="row.baselineNeedsReview" class="warning">计划变化，需核对</span></p><small>{{ row.marketEligible?'两部件验收通过，可确认上市':'尚未满足上市验收条件' }}</small></template></el-table-column>
        <el-table-column fixed="right" label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="open(row)">详情 / 历史</el-button><el-button v-if="options?.writableGroups.includes('engineering')" link @click="baseline(row)">留存计划基准</el-button><el-button v-if="drafts.rows.has(rowKey(row))" link @click="reason(row)">更正原因</el-button></template></el-table-column>
        <template #empty><div class="schedule-empty">暂无已确认的实物套。请在模具台账建套后排程；原表仅预览，不自动生成模具、颜色项目或库存。</div></template>
      </el-table></FixedTableViewport>
      <section v-else class="schedule-timeline" v-loading="request.loading.value" aria-label="本页模具排程时间轴">
        <p class="timeline-note">已确认计划 → 当前预测 → 实际记录；建议日期不进入时间轴。待保存日期仅为草稿，不代表已确认或完成；抵墨、到港不等同于到厂。</p>
        <article v-for="row in rows" :key="row.moldSetId" class="timeline-card" :data-mold-set-id="row.moldSetId">
          <header class="timeline-heading"><div><strong>{{ row.styleName }} · {{ row.compatibleModels }}</strong><p>{{ row.assetNumber }} · 第 {{ display(row.setNo) }} 套 · 已保存基准 V{{ row.planVersion || 0 }}</p></div><div class="actions"><el-tag>{{ statusNames[row.scheduleStatus] || (row.scheduleStatus==='market_ready'?'已确认上市':row.scheduleStatus) }}</el-tag><el-tag v-if="drafts.rows.has(rowKey(row))" type="warning">含待保存草稿</el-tag><el-button link @click="open(row)">详情 / 历史</el-button></div></header>
          <div class="timeline-track"><section v-for="(step,index) in milestones" :key="step.key" class="timeline-step" :data-step="step.key"><h3><span>{{ index+1 }}</span>{{ step.title }}</h3>
            <div class="timeline-layer confirmed" data-layer="plan"><label>已确认计划</label><time>{{ step.plan ? display(value(row,step.plan)) : '未填写' }}</time><small v-if="step.plan && dirty(row,step.plan)" class="warning">待保存，尚未确认</small></div>
            <div class="timeline-layer forecast" data-layer="forecast"><label>当前预测</label><time>{{ step.forecast ? display(value(row,step.forecast)) : '未填写' }}</time><small v-if="step.forecast && dirty(row,step.forecast)" class="warning">待保存</small></div>
            <div class="timeline-layer actual" data-layer="actual"><label>实际记录</label><dl v-for="entry in step.actual" :key="entry.key" :data-field="entry.key"><dt>{{ field(entry.key)?.label || entry.label }}</dt><dd>{{ display(value(row,entry.key)) }}<small v-if="dirty(row,entry.key)" class="warning"> · 待保存，非完成事实</small></dd></dl></div>
          </section></div>
          <div class="timeline-footer"><span v-if="row.baselineNeedsReview" class="warning">计划变化，需核对基准</span><el-button text :aria-expanded="expandedParts.has(row.moldSetId!)" data-test="timeline-parts-toggle" @click="toggleParts(row.moldSetId!)">{{ expandedParts.has(row.moldSetId!)?'收起':'展开' }} PC / TPU 到厂与验收</el-button><small>两部件独立记录；整套进度沿用已保存状态，不凭时间轴推算。</small></div>
          <div v-if="expandedParts.has(row.moldSetId!)" class="timeline-parts"><section v-for="p in partColumns" :key="p.part" :data-part="p.part"><h3>{{ p.part }} 到厂 / 验收</h3><div v-for="f in p.fields" :key="f.key" class="part-entry"><label>{{ f.label }}</label><CollaborationCell v-if="can(f)" :field="f" :value="value(row,f.key)" :editable="true" :dirty="dirty(row,f.key)" @preview="edit(row,f,$event,true)" @edit="edit(row,f,$event)" /><span v-else>{{ partDisplay(row,f) }}</span></div></section></div>
          <div v-if="row.tasks?.length" class="timeline-tasks"><strong>已保存计划待办</strong><span v-for="task in row.tasks" :key="task.taskKey" :class="{warning:task.overdue}">{{ task.title }} · {{ display(task.dueDate) }}{{ task.overdue?' · 已逾期':'' }}</span></div>
        </article>
        <div v-if="!rows.length" class="schedule-empty">暂无已确认的实物套。请在模具台账建套后排程。</div>
      </section>
      <el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[20,50,100]" :total="total" layout="total,sizes,prev,pager,next,jumper" @current-change="load()" />
    </section>
    <footer v-if="dirtyCount" class="schedule-save"><strong>{{ moldDrafts.length }} 套 · {{ dirtyCount }} 个字段待保存</strong><small>与协作计划、模具台账共用草稿，刷新不覆盖</small><div class="actions"><el-button @click="review=true">核对草稿 / 冲突</el-button><el-button @click="discard">撤销未保存修改</el-button><el-button type="primary" :loading="saving" data-test="save-schedules" @click="save">批量保存</el-button></div></footer>
