    <el-drawer v-model="review" title="共用模具草稿与冲突" size="90%"><section v-for="[key,d] in moldDrafts" :key="key" class="draft-card"><h3>{{ d.source.assetNumber }} · {{ d.source.styleName }} · {{ d.source.compatibleModels }}</h3><el-button link @click="reason(d.source)">{{ d.reason || '填写日期更正 / 核对原因' }}</el-button><p v-for="[name,c] in d.changes" :key="name">{{ field(name)?.label || name }}：{{ display(c.before) }} → {{ display(c.after) }}</p><el-alert v-if="d.result" :title="d.result.message" type="warning" :closable="false" /><div v-for="c in d.result?.conflicts" :key="c.field" class="conflict"><span>{{ c.label }} · 当前 {{ display(c.current) }} · 我的修改 {{ display(c.attempted) }}</span><el-button @click="drafts.resolve(key,c.field,false)">采用当前值</el-button><el-button type="warning" @click="drafts.resolve(key,c.field,true)">确认保留我的修改</el-button></div></section><template #footer><el-button type="primary" :loading="saving" @click="save">保存已核对修改</el-button></template></el-drawer>
    <CollaborationImportDialog v-if="options" v-model="importVisible" kind="schedule" :options="options" @imported="workspace.changed();load()" />
  </main>
</template>

